return-response.set-body:
@{
        return new JObject(
          new JProperty("_links", new JObject(
            new JProperty("self", new JObject(new JProperty("href", "/platform/health"))))),
          new JProperty("status", "available"),
          new JProperty("correlationId", context.Request.Headers.GetValueOrDefault("Correlation-Id", "")),
          new JProperty("checkedAt", DateTime.UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ"))
        ).ToString();
      }
